const listConnections = `-- name: ListConnections :many
SELECT id, company_id, slug, name, url, identity, owner_user_id, status, integration_id, resource, issuer, authorization_endpoint, token_endpoint, registration_endpoint, client_id, client_secret_ref, scopes, auth_state_hash, auth_verifier_enc, auth_started_by_id, auth_expires_at, expires_at, connected_at, refreshing_until, last_refresh_at, last_probe_at, last_probe_status, last_error, gate_id, created_by_type, created_by_id, created_at, updated_at FROM connections
WHERE company_id = $1 AND (identity = 'company' OR owner_user_id = $2)
ORDER BY name, id
`

type ListConnectionsParams struct {
	CompanyID    uuid.UUID
	ViewerUserID *uuid.UUID
}

// Conexões da empresa visíveis ao chamador: as da empresa e as pessoais dele.
func (q *Queries) ListConnections(ctx context.Context, arg ListConnectionsParams) ([]Connection, error) {
	rows, err := q.db.Query(ctx, listConnections, arg.CompanyID, arg.ViewerUserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Connection{}
	for rows.Next() {
		var i Connection
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.Slug,
			&i.Name,
			&i.Url,
			&i.Identity,
			&i.OwnerUserID,
			&i.Status,
			&i.IntegrationID,
			&i.Resource,
			&i.Issuer,
			&i.AuthorizationEndpoint,
			&i.TokenEndpoint,
			&i.RegistrationEndpoint,
			&i.ClientID,
			&i.ClientSecretRef,
			&i.Scopes,
			&i.AuthStateHash,
			&i.AuthVerifierEnc,
			&i.AuthStartedByID,
			&i.AuthExpiresAt,
			&i.ExpiresAt,
			&i.ConnectedAt,
			&i.RefreshingUntil,
			&i.LastRefreshAt,
			&i.LastProbeAt,
			&i.LastProbeStatus,
			&i.LastError,
			&i.GateID,
			&i.CreatedByType,
			&i.CreatedByID,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

